<?php
require "conexao.php";
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");}
function q($p=[]){return "index.php?".http_build_query(array_filter($p,fn($v)=>$v!==null&&$v!==""));}
$view=$_GET["view"]??"month"; if(!in_array($view,["month","week","day"],true))$view="month";
$today=new DateTimeImmutable("today"); $selected=$today;
if(!empty($_GET["data"])){ $d=DateTimeImmutable::createFromFormat("!Y-m-d",$_GET["data"]); if($d&&$d->format("Y-m-d")===$_GET["data"])$selected=$d; }
$month=(int)($_GET["mes"]??$selected->format("n")); $year=(int)($_GET["ano"]??$selected->format("Y"));
$month=max(1,min(12,$month)); $monthDate=new DateTimeImmutable(sprintf("%04d-%02d-01",$year,$month));
$names=[1=>"Janeiro",2=>"Fevereiro",3=>"Março",4=>"Abril",5=>"Maio",6=>"Junho",7=>"Julho",8=>"Agosto",9=>"Setembro",10=>"Outubro",11=>"Novembro",12=>"Dezembro"];
$days=["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"];
if($view==="day"){ $start=$selected;$end=$selected;$title=$selected->format("d")." de ".$names[(int)$selected->format("n")]." de ".$selected->format("Y");$subtitle="Sua agenda do dia, com foco no que precisa acontecer agora."; }
elseif($view==="week"){ $start=$selected->modify("monday this week");$end=$start->modify("+6 days");$title=$start->format("d/m")." — ".$end->format("d/m/Y");$subtitle="Uma visão compacta para equilibrar compromissos e tempo livre."; }
else{ $start=$monthDate;$end=$monthDate->modify("last day of this month");$title=$names[$month]." ".$year;$subtitle="Toque em um dia para abrir seus compromissos no painel lateral."; }
$stmt=$conexao->prepare("SELECT * FROM compromissos WHERE data_compromisso BETWEEN :i AND :f ORDER BY data_compromisso,hora_compromisso");$stmt->execute([":i"=>$start->format("Y-m-d"),":f"=>$end->format("Y-m-d")]);$items=$stmt->fetchAll(PDO::FETCH_ASSOC);$byDate=[];
foreach($items as $item)$byDate[$item["data_compromisso"]][]=$item;
$prev=$view==="day"?$selected->modify("-1 day"):($view==="week"?$start->modify("-7 days"):$monthDate->modify("-1 month"));$next=$view==="day"?$selected->modify("+1 day"):($view==="week"?$start->modify("+7 days"):$monthDate->modify("+1 month"));
$nav=fn($d,$v)=>q(["view"=>$v,"data"=>$d->format("Y-m-d"),"mes"=>$d->format("n"),"ano"=>$d->format("Y")]);$selectedKey=$selected->format("Y-m-d");$selectedItems=$byDate[$selectedKey]??[];$panel=$view==="month"&&isset($_GET["data"]);
?>
<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#15112c"><title>Hoshi Calendar · <?=h($title)?></title><link rel="stylesheet" href="css/style.css"></head>
<body><div class="ambient a1"></div><div class="ambient a2"></div><main class="app">
<header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">✦</span><span><b>Hoshi</b><small>calendar</small></span></a><div class="top-actions"><span class="today-chip">● <?=$today->format("d/m/Y")?></span><a class="btn primary" href="criar.php?data=<?=$selectedKey?>&mes=<?=$month?>&ano=<?=$year?>">＋ Novo compromisso</a></div></header>
<section class="hero"><div><p class="eyebrow">SEU TEMPO, SEU RITMO</p><h1><?=h($title)?></h1><p class="muted"><?=h($subtitle)?></p></div><nav class="views"><a class="<?=$view==="day"?"active":""?>" href="<?=$nav($selected,"day")?>">Dia</a><a class="<?=$view==="week"?"active":""?>" href="<?=$nav($selected,"week")?>">Semana</a><a class="<?=$view==="month"?"active":""?>" href="<?=$nav($monthDate,"month")?>">Mês</a></nav></section>
<section class="toolbar card"><div class="nav"><a class="icon" href="<?=$nav($prev,$view)?>">‹</a><a class="btn ghost" href="index.php">Hoje</a><a class="icon" href="<?=$nav($next,$view)?>">›</a></div><div class="legend"><span><i class="dot pink"></i> pendente</span><span><i class="dot mint"></i> concluído</span><strong><?=count($items)?> <?=count($items)===1?"compromisso":"compromissos"?></strong></div></section>
<?php if($view==="month"): ?>
<section class="month-layout"><div class="calendar card"><div class="week-head"><?php foreach($days as $day):?><span><?=$day?></span><?php endforeach;?></div><div class="grid">
<?php for($i=1;$i<(int)$monthDate->format("N");$i++):?><div class="cell empty"></div><?php endfor;?>
<?php for($day=1;$day<=(int)$end->format("d");$day++):$date=$monthDate->setDate($year,$month,$day);$key=$date->format("Y-m-d");$events=$byDate[$key]??[];?><a class="cell <?=$key===$today->format("Y-m-d")?"today":""?> <?=$key===$selectedKey&&$panel?"selected":""?>" href="<?=$nav($date,"month")?>"><b><?=$day?></b><?php if($events):?><span class="dots"><?php foreach(array_slice($events,0,4) as $event):?><i class="dot <?=$event["concluido"]?"mint":"pink"?>"></i><?php endforeach;?><?php if(count($events)>4):?><em>+<?=count($events)-4?></em><?php endif;?></span><?php endif;?><small><?=count($events)?count($events)." ".(count($events)===1?"item":"itens"):"Livre"?></small></a><?php endfor;?>
<?php for($i=(int)$end->format("N");$i<7;$i++):?><div class="cell empty"></div><?php endfor;?></div></div>
<aside class="panel card"><div class="panel-head"><div><p class="eyebrow">DETALHES DO DIA</p><h2><?=$panel?h(date("d/m",strtotime($selectedKey))):"Escolha um dia"?></h2></div><?php if($panel):?><a class="close" href="<?=q(["mes"=>$month,"ano"=>$year])?>">×</a><?php endif;?></div><?php if($panel):?><p class="muted"><?=count($selectedItems)?"Você tem ".count($selectedItems)." compromisso(s) planejado(s).":"Nenhum compromisso por aqui. Que tal respirar e aproveitar?"?></p><?php foreach($selectedItems as $event):?><article class="event <?=$event["concluido"]?"done":""?>"><time><?=h(substr($event["hora_compromisso"],0,5))?></time><div><a href="editar.php?id=<?=(int)$event["id"]?>&mes=<?=$month?>&ano=<?=$year?>"><?=h($event["titulo"])?></a><?php if($event["descricao"]):?><p><?=h($event["descricao"])?></p><?php endif;?></div><span><?=$event["concluido"]?"feito":"aberto"?></span></article><?php endforeach;?><a class="btn primary full" href="criar.php?data=<?=$selectedKey?>&mes=<?=$month?>&ano=<?=$year?>">＋ Adicionar neste dia</a><?php else:?><div class="empty-panel"><span>✦</span><p>Clique em qualquer dia para visualizar seus compromissos e adicionar um novo.</p></div><?php endif;?></aside></section>
<?php elseif($view==="week"): ?><section class="week-board card"><div class="week-columns"><?php for($i=0;$i<7;$i++):$date=$start->modify("+$i days");$key=$date->format("Y-m-d");?><div class="week-col <?=$key===$today->format("Y-m-d")?"today":""?>"><a class="week-head" href="<?=$nav($date,"day")?>"><span><?=$days[$i]?></span><b><?=$date->format("d")?></b></a><?php foreach($byDate[$key]??[] as $event):?><a class="week-event <?=$event["concluido"]?"done":""?>" href="editar.php?id=<?=(int)$event["id"]?>&mes=<?=$date->format("n")?>&ano=<?=$date->format("Y")?>"><time><?=h(substr($event["hora_compromisso"],0,5))?></time><strong><?=h($event["titulo"])?></strong><small><?=h($event["descricao"]??"")?></small></a><?php endforeach;?><a class="quick" href="criar.php?data=<?=$key?>&mes=<?=$date->format("n")?>&ano=<?=$date->format("Y")?>">＋ adicionar</a></div><?php endfor;?></div></section>
<?php else:?><section class="day-board card"><div class="day-title"><div><p class="eyebrow">AGENDA DO DIA</p><h2><?=h($selected->format("d/m/Y"))?></h2></div><a class="btn primary" href="criar.php?data=<?=$selectedKey?>&mes=<?=$month?>&ano=<?=$year?>">＋ Adicionar</a></div><?php if(!$selectedItems):?><div class="empty-panel"><span>☾</span><h3>Dia leve por aqui</h3><p>Você não tem compromissos cadastrados para esta data.</p></div><?php else:?><div class="timeline"><?php foreach($selectedItems as $event):?><article class="timeline-item <?=$event["concluido"]?"done":""?>"><time><?=h(substr($event["hora_compromisso"],0,5))?></time><div class="event"><div><a href="editar.php?id=<?=(int)$event["id"]?>&mes=<?=$month?>&ano=<?=$year?>"><?=h($event["titulo"])?></a><p><?=h($event["descricao"]??"Sem descrição adicionada.")?></p></div><span><?=$event["concluido"]?"feito":"aberto"?></span></div></article><?php endforeach;?></div><?php endif;?></section><?php endif;?>
<footer><span>✦ Hoshi Calendar</span><span>Organização com um toque de magia.</span></footer></main><script src="js/app.js"></script></body></html>
